// 来源图片: image37.png（实验一 主函数）
/**
 * Function        main
 * @author         Danny
 * @date           2017.08.16
 * @brief          循环显7色LED
 * @param[in]      void
 * @retval         void
 * @par History    无
 */
int main()
{
    //设置P4口作为普通的IO口使用
    P4SW |= (1<<4);
    P4SW |= (1<<5);
    P4SW |= (1<<6);

    //设置P4口为强推挽输出模式
    P4M1 &= ~(1<<4);
    P4M1 &= ~(1<<5);
    P4M1 &= ~(1<<6);

    P4M0 |= (1<<4);
    P4M0 |= (1<<5);
    P4M0 |= (1<<6);

    while (1)
    {
        color_led(ON, OFF, OFF);  //  LED_R  LED_G  LED_B
        delay(1000);              //     1      0      0
        color_led(OFF, ON, OFF);  //     0      1      0
        delay(1000);
        color_led(OFF, OFF, ON);  //     0      0      1
        delay(1000);
        color_led(ON, ON, OFF);   //     1      1      0
        delay(1000);
        color_led(ON, OFF, ON);   //     1      0      1
        delay(1000);
        color_led(OFF, ON, ON);   //     0      1      1
        delay(1000);
        color_led(ON, ON, ON);    //     1      1      1
    }
    return 0;
}

