// 来源图片: image63.png（舵机控制颜色）
/**
 * Function        servo_control_color
 * @author         Danny
 * @date           2017.08.16
 * @brief          舵机从0-180的转动，然后从180到0转，
 *                 同时180度角分为7个区间来表示7种不同的颜色
 * @param[in       void
 * @param[out]     void
 * @retval         void
 * @par History    无
 */
void servo_control_color()
{
    //定义舵机转动位置
    int pos = 0;
    int i = 0;
    for (pos = 1; pos < 180; pos=pos+5)
    {
        //舵机0旋转到180,每次延时5ms
        for(i=0;i<15;i++)
        {
            myangle=pos;
            delay(5);
        }
        //旋转到相应的角度，判断调用相关函数
        color_light(pos);
    }
    for (pos = 180; pos > 0; pos=pos-5)
    {
        //舵机180旋转到0,每次延时5ms
        for(i=0;i<15;i++)
        {
            myangle=pos;
            delay(5);
        }
        //旋转到相应的角度，判断调用相关函数
        color_light(pos);
    }
    return;
}

