/**
 * Function        timer1
 * @author         Danny
 * @date           2017.08.16
 * @brief          TIMER1中断服务子函数产生PWM信号，控制舵机
 * @param[in       void
 * @param[out]     void
 * @retval         void
 * @par History    无
 */
void timer1() interrupt 3
{
    int PulseWidth;
    TH1=0XFF;           //100us定时，装入初值
    TL1=0XA4;
    count++;

                            //定义脉宽变量
    PulseWidth = ((myangle*11))+500)/100 ;  //为了将0-180度转换为相应的脉宽值 // [不清：该行括号配对在原图中难以辨认，可能为 ((myangle*11)+500)/100]
    if(count == PulseWidth)
    {
        ServoPin=0;         //将舵机接口电平置高
    }
    if(count == 190)        //190为最终调试获得的一个最佳值
    {
        count = 0;
        ServoPin=1;         //将舵机接口电平置低
    }
}
