 * @par Copyright (C): 2010-2019, Shenzhen Yahboom Tech
 * @file         ColorLED.c
 * @author       Danny
 * @version      V1.0
 * @date         2017.08.16
 * @brief        七彩探照灯实验
 */
#include "STC12C5A60S2.H"

#define ON 1     //使能LED
#define OFF 0    //禁止LED

//定义RGB七彩灯引脚
sbit LED_R = P4^6;   //LED_R接在STC12C5A60S2的EA（P4^6）管脚
sbit LED_G = P4^5;   //LED_G接在STC12C5A60S2的ALE（P4^5）管脚
sbit LED_B = P4^4;   //LED_B接在STC12C5A60S2的PSEN（P4^4）管脚

/**
* Function        delay
* @brief          延时函数
* @param          xms：延时时间（ms）
*/
void delay(unsigned int xms)
{
    unsigned int i,j;
    for(i=xms;i>0;i--)
        for(j=900;j>0;j--);
}

/**
* Function        color_led
* @brief          由R,G,B三色的不同组合形成7种不同的色彩
* @param[in1]     Red开关
* @param[in2]     Green开关
* @param[in3]     Blue开关
*/
void color_led(int v_iRed, int v_iGreen, int v_iBlue)
{
    //红色LED
    v_iRed == ON ? (LED_R = 1): (LED_R = 0);

    //绿色LED
    v_iGreen == ON ? (LED_G = 1): (LED_G = 0);

    //蓝色LED
    v_iBlue == ON ? (LED_B = 1): (LED_B = 0);
}

/**
* Function        main
* @brief          循环显7色LED
*/
int main()
{
    //设置P4口作为普通的IO口使用
    P4SW |= (1<<4);
    P4SW |= (1<<5);
    P4SW |= (1<<6);

    //设置P4口为强推挽输出模式
    P4M1 &= ~(1<<4);
    P4M1 &= ~(1<<5);
    P4M1 &= ~(1<<6);

    P4M0 |= (1<<4);
    P4M0 |= (1<<5);
    P4M0 |= (1<<6);

    while (1)
    {
        color_led(ON, OFF, OFF);  //  LED_R  LED_G  LED_B
        delay(1000);              //     1      0      0
        color_led(OFF, ON, OFF);  //     0      1      0
        delay(1000);
        color_led(OFF, OFF, ON);  //     0      0      1
        delay(1000);
        color_led(ON, ON, OFF);   //     1      1      0
        delay(1000);
        color_led(ON, OFF, ON);   //     1      0      1
        delay(1000);
        color_led(OFF, ON, ON);   //     0      1      1
        delay(1000);
        color_led(ON, ON, ON);    //     1      1      1
        delay(1000);
    }
    return 0;
}
"}

