#include "STC12C5A60S2.H"

#define ON 1     //使能LED
#define OFF 0    //禁止LED

//定义RGB七彩灯引脚
sbit LED_R = P4^6;   //LED_R接在STC12C5A60S2的EA（P4^6）管脚
sbit LED_G = P4^5;   //LED_G接在STC12C5A60S2的ALE（P4^5）管脚
sbit LED_B = P4^4;   //LED_B接在STC12C5A60S2的PSEN（P4^4）管脚

//定义舵机引脚
sbit ServoPin=P0^5;

//定义定时变量和角度值
unsigned int count = 0;
unsigned char myangle = 0;

//函数声明
void color_light(int pos);
void color_led(int v_iRed, int v_iGreen, int v_iBlue);
void servo_control_color();

/**
* Function        delay
* @brief          延时函数
* @param          xms：延时时间（ms）
*/
void delay(unsigned int xms)
{
    unsigned int i,j;
    for(i=xms;i>0;i--)
        for(j=900;j>0;j--);
}

/**
* Function        color_led
* @brief          由R,G,B三色的不同组合形成7种不同的色彩
* @param[in1]     Red开关
* @param[in2]     Green开关
* @param[in3]     Blue开关
*/
void color_led(int v_iRed, int v_iGreen, int v_iBlue)
{
    //红色LED
    v_iRed == ON ? (LED_R = 1): (LED_R = 0);

    //绿色LED
    v_iGreen == ON ? (LED_G = 1): (LED_G = 0);

    //蓝色LED
    v_iBlue == ON ? (LED_B = 1): (LED_B = 0);
}

/**
* Function        color_light
* @brief          根据转动的角度来点亮相应的颜色
* @param[in]      pos  舵机的转动位置
*/
void color_light(int pos)
{
    //当转动在150-180度时,点亮一种颜色
    if (pos > 150)
    {
        color_led(ON, OFF, OFF);
    }
    //当转动在125-150度时,点亮一种颜色
    else if (pos > 125)
    {
        color_led(OFF, ON, OFF);
    }
    //当转动在100-125度时,点亮一种颜色
    else if (pos > 100)
    {
        color_led(OFF, OFF, ON);
    }
    //当转动在75-100度时,点亮一种颜色
    else if (pos > 75)
    {
        color_led(OFF, ON, ON);
    }
    //当转动在50-75度时,点亮一种颜色
    else if (pos > 50)
    {
        color_led(ON, ON, OFF);
    }
    //当转动在25-50度时,点亮一种颜色
    else if (pos > 25)
    {
        color_led(ON, OFF, ON);
    }
    //当转动在0-25度时,点亮一种颜色
    else if (pos > 0)
    {
        color_led(ON, ON, ON);
    }
    else
    {
        color_led(OFF, OFF, OFF);
    }
}

/**
* Function        servo_control_color
* @brief          舵机从0-180的转动，然后从180到0转，
*                 同时180度角分为7个区间来表示7种不同的颜色
*/
void servo_control_color()
{
    //定义舵机转动位置
    int pos = 0;
    int i = 0;
    for (pos = 1; pos < 180; pos=pos+5)
    {
        //舵机0度转到180,每次延时5ms
        for(i=0;i<15;i++)
        {
            myangle=pos;
            delay(5);
        }
        //旋转到相应的角度,判断调用相关函数
        color_light(pos);
    }
    for (pos = 180; pos > 0; pos=pos-5)
    {
        //舵机180旋转到0,每次延时5ms
        for(i=0;i<15;i++)
        {
            myangle=pos;
            delay(5);
        }
        //旋转到相应的角度,判断调用相关函数
        color_light(pos);
    }
    return;
}

/**
* Function        timer1
* @brief          TIMER1中断服务子函数产生PWM信号，控制舵机
*/
void timer1() interrupt 3
{
    int PulseWidth;
    TH1=0XFF;           //100us定时，装入初值
    TL1=0XA4;
    count++;

    PulseWidth = ((myangle*11)+500)/100 ;  //为了将0-180度转换为相应的脉宽值
    if(count == PulseWidth)
    {
        ServoPin=0;         //将舵机接口电平置低
    }
    if(count == 190)        //190为最终调试获得的一个最佳值
    {
        count = 0;
        ServoPin=1;         //将舵机接口电平置高
    }
}

/**
* Function        main
* @brief          先延时0.5s，接着调用舵机控制七彩灯程序
*/
void main()
{
    unsigned char i =0;
    TMOD=0X10;  //定时器工作方式1
    TH1=0XFF;   //100us定时，装入初值
    TL1=0XA4;
    TR1=1;      //启动T1工作
    ET1=1;      //允许T1中断
    EA =1;      //开总中断

    //设置P4口作为普通的IO口使用
    P4SW |= (1<<4);
    P4SW |= (1<<5);
    P4SW |= (1<<6);

    //设置P4口为强推挽输出模式
    P4M1 &= ~(1<<4);
    P4M1 &= ~(1<<5);
    P4M1 &= ~(1<<6);

    P4M0 |= (1<<4);
    P4M0 |= (1<<5);
    P4M0 |= (1<<6);

    //舵机引脚初始化为高电平
    ServoPin=1;

    //初始化舵机位置向前
    for(i = 0; i<15;i++)
    {
        myangle = 90;
        delay(20);
    }

    while(1)
    {
        //调用舵机控制七彩灯程序
        servo_control_color();
    }
}
