void delay(unsigned int xms)
{
    unsigned int i,j;
    for(i=xms;i>0;i--)
        for(j=900;j>0;j--);
}

void Serial_Init()
{
    SCON=0x50;
    AUXR=0x11;
    BRT=0XFD;       //9600
    ES=1;
    EA=1;
}

void uart_send_byte(unsigned char dat)
{
    SBUF = dat;
    while(TI == 0);
    TI=0;
}

void uart_send_string(unsigned char *str)
{
    while(*str != '\0')
    {
        uart_send_byte(*str);
        str++;
    }
}

void main()
{
    //P4 口配成普通 I/O + 强推挽
    P4SW |= (1<<4);  P4SW |= (1<<5);  P4SW |= (1<<6);
    P4M1 &= ~(1<<4); P4M1 &= ~(1<<5); P4M1 &= ~(1<<6);
    P4M0 |= (1<<4);  P4M0 |= (1<<5);  P4M0 |= (1<<6);
    LED_R=0; LED_G=0; LED_B=0;

    Serial_Init();
    uart_send_string("IR TEST: block sensor and watch L/R\r\n");

    while(1)
    {
        LeftSensorValue  = AvoidSensorLeft;
        RightSensorValue = AvoidSensorRight;

        //串口输出，例如 "L=1 R=1"
        uart_send_string("L=");
        uart_send_byte('0' + LeftSensorValue);
        uart_send_string("  R=");
