/**
* Function       measure_Distance
* @brief         超声波测距函数（带超时保护）
* @return        距离（cm）；没有回波时返回 999
*/
int measure_Distance()
{
    unsigned int distance;
    unsigned char l;
    unsigned int h,y;
    unsigned int timeout;

    ultrasonic_trigger();

    //等待 Echo 变高（回波开始）。模块没接好/没供电时这里会永远等下去，故加超时
    timeout = 0;
    while(!EchoPin)
    {
        if(++timeout > 20000)          //约 30ms，远超正常响应时间
        {
            TrigPin = 0;
            return 999;                //没有回波
        }
    }

    TR1 = 1;

    //等待 Echo 变低（回波结束），同样加超时
    timeout = 0;
    while(EchoPin)
    {
        if(++timeout > 20000)
        {
            TR1 = 0;
            TL1 = 0x66;
            TH1 = 0xfc;
            count = 0;
            TrigPin = 0;
            return 999;
        }
    }

    TR1 = 0;
    l = TL1;
    h = TH1;
    y = (h<<8) + l;
    y = y - 0xfc66;
    distance = y + 1000 * count;
    TL1 = 0x66;
    TH1 = 0xfc;
    distance = 0.017 * distance;
    TrigPin = 0;
    count = 0;

    return distance;
}
```

